<?php
require_once __DIR__ . '/../config/app.php'; require_admin();
$pageTitle='Metode Pembayaran';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='delete'){$id=(int)$_POST['id'];$q=$pdo->prepare('SELECT COUNT(*) FROM transactions WHERE payment_method_id=?');$q->execute([$id]);if((int)$q->fetchColumn())$error='Metode sudah dipakai transaksi. Nonaktifkan agar riwayat tetap utuh.';else{$q=$pdo->prepare('DELETE FROM payment_methods WHERE id=?');$q->execute([$id]);set_flash('success','Metode dihapus.');redirect('/admin/payments.php');}}else{$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$desc=trim($_POST['description']??'');$active=isset($_POST['is_active'])?1:0;if($name==='')$error='Nama metode wajib diisi.';else{if($id){$q=$pdo->prepare('UPDATE payment_methods SET name=?,description=?,is_active=? WHERE id=?');$q->execute([$name,$desc,$active,$id]);}else{$q=$pdo->prepare('INSERT INTO payment_methods(name,description,is_active) VALUES(?,?,?)');$q->execute([$name,$desc,$active]);}set_flash('success','Metode pembayaran disimpan.');redirect('/admin/payments.php');}}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM payment_methods WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$items=$pdo->query('SELECT * FROM payment_methods ORDER BY id DESC')->fetchAll();
require __DIR__.'/../includes/header.php';
?>
<div class="page-head"><div><span class="eyebrow">ADMIN / PEMBAYARAN</span><h1>Metode Pembayaran</h1></div><a class="text-link" href="<?=BASE_URL?>/admin/index.php">← Dashboard</a></div>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?>
<div class="two-col admin-form-layout"><form class="panel" method="post"><h2><?=$edit?'Edit Metode':'Tambah Metode'?></h2><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><label>Nama metode<input name="name" required value="<?=e($edit['name']??'')?>"></label><label>Keterangan<textarea name="description" rows="3"><?=e($edit['description']??'')?></textarea></label><label class="check"><input type="checkbox" name="is_active" <?=(!isset($edit['is_active'])||(int)$edit['is_active']===1)?'checked':''?>> Aktif</label><button class="btn" name="action" value="save">Simpan</button><?php if($edit):?> <a href="<?=BASE_URL?>/admin/payments.php">Batal</a><?php endif;?></form>
<div class="panel table-wrap"><h2>Daftar Metode</h2><table><thead><tr><th>Nama</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($items as $p):?><tr><td><?=e($p['name'])?><br><small><?=e($p['description'])?></small></td><td><?=$p['is_active']?'Aktif':'Nonaktif'?></td><td><a href="?edit=<?=(int)$p['id']?>">Edit</a><form class="inline-form" method="post" onsubmit="return confirm('Hapus metode ini?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$p['id']?>"><button class="danger-link" name="action" value="delete">Hapus</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
